def solve(grid):
    """Count the number of islands (connected components of 1s) in a grid.
    Connectivity is 4-directional (up, down, left, right).
    """
    if not grid:
        return 0
    n = len(grid)
    m = len(grid[0]) if n else 0
    visited = [[False]*m for _ in range(n)]
    dirs = [(1,0),(-1,0),(0,1),(0,-1)]
    def dfs(i, j):
        stack = [(i, j)]
        visited[i][j] = True
        while stack:
            x, y = stack.pop()
            for dx, dy in dirs:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and grid[nx][ny] == 1:
                    visited[nx][ny] = True
                    stack.append((nx, ny))
    count = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1 and not visited[i][j]:
                count += 1
                dfs(i, j)
    return count

