def solve(s):
    # Ensure we have a string; if not, attempt to decode bytes, otherwise convert to string.
    if not isinstance(s, str):
        try:
            s = s.decode()
        except Exception:
            s = str(s)
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
        # ignore other characters
    return not stack

