def solve(s):
    """Convert a Roman numeral to an integer.
    Handles uppercase and lowercase input, ignores surrounding whitespace,
    and returns 0 for non‑string or empty inputs.
    """
    if not isinstance(s, str):
        return 0
    s = s.strip().upper()
    if not s:
        return 0
    values = {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
    total = 0
    i = 0
    n = len(s)
    while i < n:
        if i+1 < n and values.get(s[i],0) < values.get(s[i+1],0):
            total += values[s[i+1]] - values[s[i]]
            i += 2
        else:
            total += values.get(s[i],0)
            i += 1
    return total

