def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Handles empty input and non-list inputs gracefully.
    """
    # Ensure we have an iterable of numbers
    if not isinstance(nums, (list, tuple)):
        try:
            nums = list(nums)
        except Exception:
            return 0
    if not nums:
        return 0
    import bisect
    tails = []
    for x in nums:
        # find insertion point
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

